// Daten aller Quellen einsammeln und Prompt für die Zusammenfassung bauen
function safeAll(name) {
  try { return $(name).all().filter(i => i.json && Object.keys(i.json).length > 0); }
  catch (e) { return []; }
}

function absender(j) {
  return (j.from && j.from.value && j.from.value[0] && j.from.value[0].address)
    || (j.from && j.from.text)
    || j.From
    || (typeof j.from === 'string' ? j.from : '')
    || 'unbekannt';
}

const quellen = [
  ['Gmail', 'Gmail (letzte 24h)'],
  ['Web.de', 'Web.de (letzte 24h)'],
  ['Mailcow', 'Mailcow (letzte 24h)'],
];

const zeilen = [];
for (const [label, nodeName] of quellen) {
  for (const item of safeAll(nodeName)) {
    const j = item.json;
    const betreff = j.subject || j.Subject || '(kein Betreff)';
    zeilen.push(`[${label}] ${absender(j)} — ${betreff}`);
  }
}

const quarantaene = [];
for (const item of safeAll('Rspamd-Quarantäne')) {
  const j = item.json;
  if (j.subject !== undefined || j.sender !== undefined) {
    quarantaene.push(`${j.sender || '?'} — ${j.subject || '(kein Betreff)'} (Score ${j.score ?? '?'})`);
  }
}

const heute = $now.toFormat('dd.MM.yyyy');
const promptText = `Erstelle aus den folgenden E-Mail-Daten eine kompakte taegliche Zusammenfassung auf Deutsch fuer eine Telegram-Nachricht (max. 3000 Zeichen, kein Markdown, klare Absaetze).\n\nAufbau:\n1. Ueberschrift mit Datum ${heute}\n2. Wichtige Mails zuerst (persoenliche Mails, Rechnungen, Fristen) mit Absender und Betreff\n3. Kurze Zaehler-Zeile (z.B. "12 Mails gesamt: 3 wichtig, 5 Newsletter, ...")\n4. Abschnitt "Rspamd-Quarantaene" mit der Liste unten (falls leer: "keine Eintraege")\n\nMails der letzten 24 Stunden (${zeilen.length} Stueck):\n${zeilen.join('\n') || '(keine)'}\n\nRspamd-Quarantaene (${quarantaene.length} Eintraege):\n${quarantaene.join('\n') || '(keine)'}`;

return [{ json: { promptText, anzahlMails: zeilen.length, anzahlQuarantaene: quarantaene.length } }];

let digest = '';
try { digest = $json.candidates[0].content.parts[0].text; } catch (e) {}
if (!digest) digest = 'Digest konnte nicht erstellt werden — Gemini-Antwort war leer. Bitte Execution in n8n pruefen.';
// Telegram-Limit: 4096 Zeichen
digest = String(digest).slice(0, 4000);
return { json: { digest } };
